import Foundation
import Testing
@testable import KEFKit

/// Expected values generated by running pykefcontrol 1.0.1's own `_auth.sign()`,
/// `derive_password()`, `add_user_payload()` and `_protocol.dumps()` with fixed
/// nonces and timestamps (see scripts/signing_vectors.py).
struct SigningTests {
    static let username = "7f3c2a91-4d0b-4f65-9b3a-8e2f1c6d4a13"

    struct Vector: Sendable, CustomTestStringConvertible {
        let url: String
        let body: String?
        let nonce: String
        let ts: Int64
        let header: String
        var testDescription: String { "\(url) nonce=\(nonce)" }
    }

    static let vectors: [Vector] = [
        Vector(
            url: "https://192.168.1.78:4430/api/setData",
            body: #"{"path":"player:volume","role":"value","value":{"type":"i32_","i32_":42}}"#,
            nonce: "AbCdEfGh", ts: 1_700_000_000_000,
            header: "HMAC_SHA256 N2YzYzJhOTEtNGQwYi00ZjY1LTliM2EtOGUyZjFjNmQ0YTEz.QWJDZEVmR2g=.1700000000000.bbybu7t6q8+jnmk9c+ii210MBJgSdHS9+OSvnsnsg2o="),
        Vector(
            url: "https://192.168.1.78:4430/api/event/modifyQueue",
            body: #"{"subscribe":[{"path":"player:volume","type":"itemWithValue"}],"unsubscribe":[]}"#,
            nonce: "q1w2e3r4", ts: 1_732_400_000_123,
            header: "HMAC_SHA256 N2YzYzJhOTEtNGQwYi00ZjY1LTliM2EtOGUyZjFjNmQ0YTEz.cTF3MmUzcjQ=.1732400000123.PrAFhb/OtxJKg8Rnd2n4/TvzgzPI46K4i0dnosW7iqU="),
        Vector(
            url: "https://192.168.1.78:4430/api/setData",
            body: #"{"path":"settings:/deviceName","role":"value","value":{"type":"string_","string_":"Café ✓"}}"#,
            nonce: "Zz9+/A==", ts: 1,
            header: "HMAC_SHA256 N2YzYzJhOTEtNGQwYi00ZjY1LTliM2EtOGUyZjFjNmQ0YTEz.Wno5Ky9BPT0=.1.mEMa9mi2ZLwRdmPbHk6TPm77bzJ5G4ZKWZFgTURiC44="),
        Vector(
            url: "https://192.168.1.78:4430/api/getData?path=settings%3A%2FdeviceName&roles=value",
            body: nil,
            nonce: "nonce000", ts: 1_700_000_000_000,
            header: "HMAC_SHA256 N2YzYzJhOTEtNGQwYi00ZjY1LTliM2EtOGUyZjFjNmQ0YTEz.bm9uY2UwMDA=.1700000000000.SRKq4ETDl7Uud/V7xigDtU2Zgr0qhFf3v4KYqGo56ps="),
    ]

    @Test func defaultCredentials() {
        #expect(Credentials.default.username == Self.username)
        #expect(Credentials.default.password == "92313c2d5b721cd1541642a5f3db3db0")
        #expect(!Credentials.default.description.contains(Credentials.default.password))
    }

    @Test func addUserBodyMatchesPython() {
        let expected = #"{"path":"webserver:addUser","role":"activate","value":{"name":"7f3c2a91-4d0b-4f65-9b3a-8e2f1c6d4a13","password":"92313c2d5b721cd1541642a5f3db3db0","title":""}}"#
        #expect(Credentials.default.addUserPayload.compactString == expected)
    }

    @Test(arguments: vectors)
    func signatureMatchesPython(_ vector: Vector) {
        let header = Signer.authorization(
            credentials: .default, url: vector.url, body: vector.body.map { Data($0.utf8) },
            nonce: vector.nonce, timestampMs: vector.ts)
        #expect(header == vector.header)
    }

    /// The bodies our request builders produce are byte-identical to Python's, so the
    /// signatures above are the signatures of what we actually send.
    @Test func requestBodiesMatchPython() throws {
        let volume = KEFRequest.setData(KEFPath.volume, .typed(ValueType.i32, 42))
        #expect(String(decoding: try #require(volume.body), as: UTF8.self) == Self.vectors[0].body)

        let queue = KEFRequest.modifyQueue(subscribe: [KEFPath.volume], queueID: nil)
        #expect(String(decoding: try #require(queue.body), as: UTF8.self) == Self.vectors[1].body)

        let name = KEFRequest.setData(KEFPath.deviceName, .typed(ValueType.string, "Café ✓"))
        #expect(String(decoding: try #require(name.body), as: UTF8.self) == Self.vectors[2].body)

        #expect(KEFRequest.getData(KEFPath.deviceName).target == "/api/getData?path=settings%3A%2FdeviceName&roles=value")
    }

    @Test func randomNonceShape() {
        let nonce = Signer.randomNonce()
        #expect(nonce.count == 8)
        #expect(Data(base64Encoded: nonce)?.count == 6)
        #expect(Signer.randomNonce() != nonce)
    }

    @Test func liveHeaderShape() {
        let header = Signer.authorization(credentials: .default, url: "https://h:4430/api/setData", body: Data("{}".utf8))
        let parts = header.dropFirst("HMAC_SHA256 ".count).split(separator: ".")
        #expect(header.hasPrefix("HMAC_SHA256 "))
        #expect(parts.count == 4)
        let ms = Int64(parts[2]) ?? 0
        #expect(abs(Double(ms) / 1000 - Date().timeIntervalSince1970) < 5)
    }
}
